  import { createFFmpeg, fetchFile } from '@ffmpeg/ffmpeg';
  import { BASE_URL } from '@/config';
  const ffmpeg = createFFmpeg({ log: true });
  let ffmpegLoaded = false;
  export async function compressVideo(file, onProgress) {
    if (!ffmpegLoaded) {
      await ffmpeg.load({
        coreURL: new URL(`${BASE_URL}/assets/ffmpeg/ffmpeg-core.js`, import.meta.url).href,
        wasmURL: new URL(`${BASE_URL}/assets/ffmpeg/ffmpeg-core.wasm`, import.meta.url).href,
        workerURL: new URL(`${BASE_URL}/assets/ffmpeg/ffmpeg-core.worker.js`, import.meta.url).href,
      });
      ffmpegLoaded = true;
    }
    if (onProgress) {
      ffmpeg.setProgress(({ ratio }) => {
        onProgress(Math.round(ratio * 100));
      });
    }
    await ffmpeg.FS('writeFile', 'input.mp4', await fetchFile(file));
    await ffmpeg.run('-i', 'input.mp4', '-vf', 'scale=640:-1', '-b:v', '800k', '-c:a', 'aac', 'output.mp4');
    const data = ffmpeg.FS('readFile', 'output.mp4');
    const compressedBlob = new Blob([data.buffer], { type: 'video/mp4' });
    const compressedFile = new File([compressedBlob], file.name.replace(/\.\w+$/, '_compressed.mp4'), { type: 'video/mp4' });
    return compressedFile;
}
